/**
 * `effect/MobEffectBase.java`: the base class of every ejected status effect (ADR 0055 D10),
 * mirroring the runtime's `MsmMobEffect` and its registration in `MsmRegistrar.registerEffect`
 * (Minecraft 26.3, Mojang names, Fabric API). Each effect gets a subclass that sets category,
 * colour, particle, sound and attribute modifiers and overrides the event hooks. The runtime's
 * findings (ADR 0055 Status) hold here too: `msm:on_start` from `onEffectAdded` (only when the
 * effect is new), `msm:on_tick` and `msm:on_end` queued to Fabric's `END_SERVER_TICK`, and
 * `msm:on_end` from `ServerMobEffectEvents.AFTER_REMOVE` (removal and expiry). Written only when
 * the project has an effect.
 *
 * @packageDocumentation
 */

import { javaString } from '../java';

/**
 * The source of `<package>/effect/MobEffectBase.java`.
 *
 * @param javaPackage - The mod's Java package.
 * @param modId - The mod id, used as the logger name.
 */
export function mobEffectBaseJava(javaPackage: string, modId: string): string {
  return `// Generated by MCSuperMods: msm:effect as the runtime's MsmMobEffect.
package ${javaPackage}.effect;

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.function.BiConsumer;
import net.fabricmc.fabric.api.entity.event.v1.effect.ServerMobEffectEvents;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerLifecycleEvents;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;
import net.minecraft.core.Holder;
import net.minecraft.core.particles.ParticleOptions;
import net.minecraft.core.particles.ParticleType;
import net.minecraft.core.particles.SimpleParticleType;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.Identifier;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.sounds.SoundEvent;
import net.minecraft.world.effect.MobEffect;
import net.minecraft.world.effect.MobEffectCategory;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.ai.attributes.Attribute;
import net.minecraft.world.entity.ai.attributes.AttributeModifier;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * A status effect whose events are generated methods of the subclass:
 * <ul>
 *   <li>{@code msm:on_start} from {@link #onEffectAdded}, on the server only: vanilla calls it when the entity did not
 *       have the effect yet ({@code onEffectStarted} runs on every {@code addEffect}, also when the effect is only
 *       refreshed);</li>
 *   <li>{@code msm:on_tick} every {@link #tickInterval} ticks of the remaining duration;</li>
 *   <li>{@code msm:on_end} from Fabric API's {@code ServerMobEffectEvents.AFTER_REMOVE}: on removal (milk, totems,
 *       commands) and when the effect runs out.</li>
 * </ul>
 * {@code msm:on_tick} and {@code msm:on_end} are queued and run at the end of the server tick: vanilla calls both while
 * it iterates the holder's effects, so an action that adds or removes an effect there would throw
 * {@code ConcurrentModificationException}. A queued tick is skipped once the holder is removed.
 */
public abstract class MobEffectBase extends MobEffect {
    private static final Logger LOGGER = LoggerFactory.getLogger(${javaString(modId)});

    /** The effect id, for log messages and attribute modifier ids. */
    private final String owner;
    /** A particle type without options shown instead of the tinted swirl, or null. */
    private final ParticleOptions particle;

    /**
     * @param owner    the effect id
     * @param particle a particle type id, or null for vanilla's tinted swirl; one that is not a particle type without
     *                 options is logged and the swirl stays
     */
    protected MobEffectBase(String owner, MobEffectCategory category, int color, String particle) {
        super(category, color);
        this.owner = owner;
        this.particle = particle == null ? null : simpleParticle(owner, particle);
    }

    private static ParticleOptions simpleParticle(String owner, String id) {
        Identifier particle = Identifier.parse(id);
        ParticleType<?> type = BuiltInRegistries.PARTICLE_TYPE.getValue(particle);
        if (BuiltInRegistries.PARTICLE_TYPE.containsKey(particle) && type instanceof SimpleParticleType simple) {
            return simple;
        }
        LOGGER.warn("{}: particle {} is not a particle type without options; the tinted swirl is used", owner, id);
        return null;
    }

    /** The particle instead of the tinted swirl, as vanilla's particle constructor of {@code MobEffect}. */
    @Override
    public ParticleOptions createParticleOptions(MobEffectInstance instance) {
        return particle != null ? particle : super.createParticleOptions(instance);
    }

    /** Plays a sound when the effect is added; an unknown sound is logged and nothing is played. */
    protected void soundOnAdded(String id) {
        Optional<SoundEvent> sound = BuiltInRegistries.SOUND_EVENT.getOptional(Identifier.parse(id));
        if (sound.isPresent()) {
            withSoundOnAdded(sound.get());
        } else {
            LOGGER.warn("{}: unknown sound {}; no sound is played when the effect is added", owner, id);
        }
    }

    /**
     * Adds an attribute modifier with the id {@code <namespace>:effect.<path>.<index>}; vanilla multiplies the amount
     * by the level. An unknown attribute is logged and the modifier is skipped.
     */
    protected void modifier(int index, String attribute, float amount, AttributeModifier.Operation operation) {
        Optional<Holder.Reference<Attribute>> holder = BuiltInRegistries.ATTRIBUTE.get(Identifier.parse(attribute));
        if (holder.isEmpty()) {
            LOGGER.error("{}: attribute_modifiers[{}]: unknown attribute {}; the modifier is skipped", owner, index, attribute);
            return;
        }
        Identifier effect = Identifier.parse(owner);
        addAttributeModifier(holder.get(), Identifier.fromNamespaceAndPath(effect.getNamespace(), "effect." + effect.getPath() + "." + index),
                amount, operation);
    }

    /** The ticks between two {@code msm:on_tick} firings at {@code amplifier}; 0 without {@code msm:on_tick}. */
    protected int tickInterval(int amplifier) {
        return 0;
    }

    /** {@code msm:on_start}; nothing by default. */
    protected void onStart(ServerLevel level, LivingEntity holder) {}

    /** {@code msm:on_tick}; nothing by default. */
    protected void onTick(ServerLevel level, LivingEntity holder) {}

    /** Whether the effect has {@code msm:on_end}. */
    protected boolean hasOnEnd() {
        return false;
    }

    /** {@code msm:on_end}; nothing by default. */
    protected void onEnd(ServerLevel level, LivingEntity holder) {}

    /** {@code duration % interval == 0}; never without {@code msm:on_tick}. */
    @Override
    public boolean shouldApplyEffectTickThisTick(int duration, int amplifier) {
        int interval = tickInterval(amplifier);
        return interval > 0 && duration % interval == 0;
    }

    /** Queues {@code msm:on_tick} for the end of the tick; the effect stays (returns {@code true}). */
    @Override
    public boolean applyEffectTick(ServerLevel level, LivingEntity entity, int amplifier) {
        if (tickInterval(amplifier) > 0) {
            queue(level, entity, this::onTick, true);
        }
        return true;
    }

    /** Plays the sound on adding (vanilla), then fires {@code msm:on_start}; called only when the effect is new. */
    @Override
    public void onEffectAdded(LivingEntity entity, int amplifier) {
        super.onEffectAdded(entity, amplifier);
        if (entity.level() instanceof ServerLevel level) {
            onStart(level, entity);
        }
    }

    /** An event waiting for the end of the server tick; {@code whileAlive} skips it once the holder is removed. */
    private record Pending(BiConsumer<ServerLevel, LivingEntity> hook, ServerLevel level, LivingEntity holder, boolean whileAlive) {}

    private static final List<Pending> PENDING = new ArrayList<>();

    private static void queue(ServerLevel level, LivingEntity holder, BiConsumer<ServerLevel, LivingEntity> hook, boolean whileAlive) {
        PENDING.add(new Pending(hook, level, holder, whileAlive));
    }

    /** Runs the queued events, including any that they queue in turn (each tick of those is a later tick). */
    private static void flush() {
        if (PENDING.isEmpty()) {
            return;
        }
        List<Pending> due = new ArrayList<>(PENDING);
        PENDING.clear();
        for (Pending p : due) {
            if (p.whileAlive() && p.holder().isRemoved()) {
                continue;
            }
            p.hook().accept(p.level(), p.holder());
        }
    }

    /** Installs the {@code msm:on_end} hook and the end-of-tick queue; called once by {@code ModEffects.register}. */
    public static void registerHooks() {
        ServerMobEffectEvents.AFTER_REMOVE.register((instance, entity, context) -> {
            if (instance.getEffect().value() instanceof MobEffectBase effect && effect.hasOnEnd()
                    && entity.level() instanceof ServerLevel level) {
                queue(level, entity, effect::onEnd, false);
            }
        });
        ServerTickEvents.END_SERVER_TICK.register(server -> flush());
        // A stopping server must not leave events for the next one (integrated server restarts).
        ServerLifecycleEvents.SERVER_STOPPED.register(server -> PENDING.clear());
    }
}
`;
}
